// src/resolver/auth-fields.ts
import path4 from "path";
import { set } from "es-toolkit/compat";
async function getUserDocumentContext(tinaSchema, resolver) {
  const collection = tinaSchema.getCollections().find((c) => c.isAuthCollection);
  if (!collection) {
    throw new Error("Auth collection not found");
  }
  const userFields = mapUserFields(collection, ["_rawData"]);
  if (!userFields.length) {
    throw new Error(`No user field found in collection ${collection.name}`);
  }
  if (userFields.length > 1) {
    throw new Error(
      `Multiple user fields found in collection ${collection.name}`
    );
  }
  const userField = userFields[0];
  const relativePath = "index.json";
  const realPath = path4.join(collection.path, relativePath);
  const userDoc = await resolver.getDocument(realPath);
  const users = get(userDoc, userField.path);
  if (!users) {
    throw new Error("No users found");
  }
  return { collection, userField, users, userDoc, relativePath };
}
function findUserInCollection(users, userField, userSub) {
  const { idFieldName } = userField;
  if (!idFieldName) {
    throw new Error("No uid field found on user field");
  }
  return users.find((u) => u[idFieldName] === userSub) || null;
}
async function handleAuthenticate({
  tinaSchema,
  resolver,
  sub,
  password,
  ctxUser
}) {
  const userSub = sub || ctxUser?.sub;
  const { userField, users } = await getUserDocumentContext(
    tinaSchema,
    resolver
  );
  const user = findUserInCollection(users, userField, userSub);
  if (!user) {
    return null;
  }
  const { passwordFieldName } = userField;
  const saltedHash = get(user, [passwordFieldName || "", "value"]);
  if (!saltedHash) {
    throw new Error("No password field found on user field");
  }
  const matches = await checkPasswordHash({
    saltedHash,
    password
  });
  return matches ? user : null;
}
async function handleAuthorize({
  tinaSchema,
  resolver,
  sub,
  ctxUser
}) {
  const userSub = sub || ctxUser?.sub;
  const { userField, users } = await getUserDocumentContext(
    tinaSchema,
    resolver
  );
  const user = findUserInCollection(users, userField, userSub);
  return user ? user : null;
}
async function handleUpdatePassword({
  tinaSchema,
  resolver,
  password,
  ctxUser
}) {
  if (!ctxUser?.sub) {
    throw new Error("Not authorized");
  }
  if (!password) {
    throw new Error("No password provided");
  }
  const { collection, userField, users, relativePath } = await getUserDocumentContext(tinaSchema, resolver);
  const { idFieldName, passwordFieldName } = userField;
  const user = users.find((u) => u[idFieldName] === ctxUser.sub);
  if (!user) {
    throw new Error("Not authorized");
  }
  user[passwordFieldName] = {
    value: password,
    passwordChangeRequired: false
  };
  const newBody = {};
  set(
    newBody,
    userField.path.slice(1),
    // remove _rawData from users path
    users.map((u) => {
      if (user[idFieldName] === u[idFieldName]) {
        return user;
      }
      return {
        // don't overwrite other users' passwords
        ...u,
        [passwordFieldName]: {
          ...u[passwordFieldName],
          value: ""
        }
      };
    })
  );
  await resolver.resolveUpdateDocument({
    collectionName: collection.name,
    relativePath,
    newBody
  });
  return true;
}

